// ============================================================================
// RLE4K Mask Lookup Module (Core Decoder)
// ============================================================================
// Description: Core decoding logic using mask lookup tables
//              Based on DPUV19 RLE112 Decompress.vhd design
//              Segment Mode directly generated, no lookup table required (revised version)
// Author: Generated by Claude Code
// Date: 2026-01-09
// ============================================================================

`timescale 1ns / 1ps

module rle4k_decoder_mask_lut (
    input  wire        clk,
    input  wire        rst_n,

    // Input: Parsed code parameters
    input  wire        code_valid,
    input  wire        is_bit_mode,
    input  wire        code_color,
    input  wire [5:0]  code_length,      // Bit mode: 1-63 bits, Segment Mode: 1-63 blocks
    input  wire        is_line_end,
    output reg         code_ready,       // Ready to accept new code

    // Output: Decoded data
    output reg         output_valid,
    output reg  [511:0] output_data,
    output reg  [9:0]  output_length,    // 实际输出的位数
    output reg         output_line_end
);

// ============================================================================
// Mask Tables Instance
// ============================================================================
wire [5:0] start_mask_index;
wire [5:0] end_mask_index;
wire [63:0] start_mask_data;
wire [63:0] end_mask_data;

rle4k_decoder_mask_tables u_mask_tables (
    .clk             (clk),
    .rst_n           (rst_n),
    .start_mask_index (start_mask_index),
    .start_mask_data (start_mask_data),
    .end_mask_index   (end_mask_index),
    .end_mask_data   (end_mask_data)
);

// ============================================================================
// Bit Mode Processing
// Similar to RLE112 DecompressDataRemain_128bit logic
// ============================================================================
reg [63:0] bit_accumulator;    // 64-bit accumulator
reg [5:0]  bit_offset;         // Current bit offset (0-63)

// Bit mode state machine
localparam BIT_IDLE   = 2'd0;
localparam BIT_LOOKUP = 2'd1;
localparam BIT_ACCUM  = 2'd2;
localparam BIT_OUTPUT = 2'd3;

reg [1:0] bit_state;

// Mask lookup table address (Compatible with DPUV19 logic)
// start_mask[offset]: Clear bits[offset-1:0], keep bits[63:offset]
// end_mask[offset+length-1]: Keep bits[offset+length-1:0], clear bits[63:offset+length]
// run_mask = start_mask & end_mask generates 'length' ones at position [offset+length-1:offset]
assign start_mask_index = bit_offset;
assign end_mask_index   = (bit_offset + code_length > 64) ? 6'd63 : (bit_offset + code_length - 1);

// Mask synthesis (similar to RLE112 Decompress.vhd:357)
// Note: run_mask should be calculated in BIT_LOOKUP state, after mask tables are read
reg [63:0] run_mask;
always @(posedge clk) begin
    if (!rst_n) begin
        run_mask <= 64'h0;
    end else if (bit_state == BIT_LOOKUP) begin
        // Calculate run_mask after mask tables are read (1 cycle delay)
        run_mask <= start_mask_data & end_mask_data;
    end
end
reg [5:0] code_length_reg;
reg       code_color_reg;

always @(posedge clk) begin
    if (!rst_n) begin
        bit_accumulator <= 64'h0;
        bit_offset      <= 6'd0;
        bit_state       <= BIT_IDLE;
        output_valid    <= 1'b0;
        output_data     <= 512'h0;
        output_length   <= 10'd0;
        output_line_end <= 1'b0;
        code_length_reg <= 6'd0;
        code_color_reg  <= 1'b0;
        code_ready      <= 1'b1;         // Ready to accept code after reset
    end else begin
        case (bit_state)
            BIT_IDLE: begin
                output_valid <= 1'b0;
                code_ready <= 1'b1;          // Ready to accept new code in IDLE state

                if (code_valid && is_line_end && code_ready) begin
                    // Line end: force output accumulator data
                    if (bit_offset > 0) begin
                        output_valid    <= 1'b1;
                        output_data     <= {448'h0, bit_accumulator};  // Zero-pad to 512 bits
                        output_length   <= {4'd0, bit_offset};
                        output_line_end <= 1'b1;
                        bit_accumulator <= 64'h0;
                        bit_offset      <= 6'd0;
                        // Keep code_ready = 1, output_fifo can buffer the data
                    end else begin
                        output_valid    <= 1'b1;
                        output_data     <= 512'h0;
                        output_length   <= 10'd0;
                        output_line_end <= 1'b1;
                        // Keep code_ready = 1, output_fifo can buffer the data
                    end
                end else if (code_valid && is_bit_mode && code_ready) begin
                    // Bit mode: start lookup
                    code_length_reg <= code_length;
                    code_color_reg  <= code_color;
                    bit_state       <= BIT_LOOKUP;
                    code_ready      <= 1'b0;     // Not ready while processing
                end else if (code_valid && !is_bit_mode && code_ready) begin
                    // Segment Mode: handled in top-level module
                    bit_state <= BIT_IDLE;
                end
            end

            BIT_LOOKUP: begin
                // Wait for lookup completion (1 cycle delay)
                bit_state <= BIT_ACCUM;
            end

            BIT_ACCUM: begin
                // Accumulate data (similar to RLE112 Decompress.vhd:357)
                if (code_color_reg == 1'b1) begin
                    // 1b run: OR operation
                    bit_accumulator <= bit_accumulator | run_mask;
                end
                // 0b run: keep unchanged

                // Update bit offset
                if (bit_offset + code_length_reg >= 64) begin
                    // Cross 64-bit boundary: output data
                    bit_offset <= (bit_offset + code_length_reg) - 64;
                    bit_state  <= BIT_OUTPUT;
                    code_ready <= 1'b0;  // Not ready during output
                end else begin
                    // No boundary crossing: continue accumulation
                    bit_offset <= bit_offset + code_length_reg;
                    bit_state  <= BIT_IDLE;      // Return to IDLE, ready for next code
                    code_ready <= 1'b1;          // Ready immediately
                end
            end

            BIT_OUTPUT: begin
                // Output 64-bit data
                output_valid  <= 1'b1;
                output_data   <= {448'h0, bit_accumulator};
                output_length <= 10'd64;

                // Reset accumulator
                bit_accumulator <= 64'h0;
                bit_state       <= BIT_IDLE;     // Return to IDLE, ready for next code
                code_ready      <= 1'b1;         // Ready immediately
            end
        endcase
    end
end

endmodule
